const gcd=(a,b)=>b?gcd(b,a%b):a<0n?-a:a;
function rational(n,d=1n){if(!d)throw Error('zero');if(d<0n){n=-n;d=-d}const g=gcd(n,d);return[n/g,d/g];}
function value(n,exact=null){if(!Number.isFinite(n))throw Error('domain');return{value:n,exact};}
function number(s){const [a,b='']=s.split('.');const d=10n**BigInt(b.length);return value(Number(s),rational(BigInt((a||'0')+b),d));}
function operation(op,a,b){let exact=null;const x=a.exact,y=b.exact;if(op==='/'&&b.value===0)throw Error('zero');if(x&&y){if(op==='+')exact=rational(x[0]*y[1]+y[0]*x[1],x[1]*y[1]);if(op==='-')exact=rational(x[0]*y[1]-y[0]*x[1],x[1]*y[1]);if(op==='*')exact=rational(x[0]*y[0],x[1]*y[1]);if(op==='/')exact=rational(x[0]*y[1],x[1]*y[0]);if(op==='^'&&y[1]===1n&&Math.abs(b.value)<=100){if(a.value===0&&b.value<0)throw Error('zero');const k=BigInt(Math.abs(b.value));exact=b.value<0?rational(x[1]**k,x[0]**k):rational(x[0]**k,x[1]**k);}}
 return value(op==='+'?a.value+b.value:op==='-'?a.value-b.value:op==='*'?a.value*b.value:op==='/'?a.value/b.value:a.value**b.value,exact);}
export function evaluate(source,{angle='DEG',ans=value(0,[0n,1n])}={}){
 const input=source.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').replaceAll('π','pi').replace(/\s/g,'');if(input.length>1500)throw Error('limit');const tokens=input.match(/\d*\.?\d+|[A-Za-z]+|[()+*/^!,%\-]/g)||[];if(!input||tokens.join('')!==input)throw Error('syntax');let i=0,depth=0;
 const call=(fn,args)=>{const a=args[0];if(!a)throw Error('syntax');const x=a.value,u=angle==='DEG'?Math.PI/180:1;let n;switch(fn){case'sin':n=Math.sin(x*u);break;case'cos':n=Math.cos(x*u);break;case'tan':if(Math.abs(Math.cos(x*u))<1e-12)throw Error('domain');n=Math.tan(x*u);break;case'asin':n=Math.asin(x)/u;break;case'acos':n=Math.acos(x)/u;break;case'atan':n=Math.atan(x)/u;break;case'log':n=Math.log10(x);break;case'ln':n=Math.log(x);break;case'exp':n=Math.exp(x);break;case'abs':return value(Math.abs(x),a.exact?rational(a.exact[0]<0n?-a.exact[0]:a.exact[0],a.exact[1]):null);case'sqrt':n=Math.sqrt(x);if(a.exact&&x>=0){const r=Math.round(Math.sqrt(Number(a.exact[0]))),d=Math.round(Math.sqrt(Number(a.exact[1])));if(BigInt(r)**2n===a.exact[0]&&BigInt(d)**2n===a.exact[1])return value(n,rational(BigInt(r),BigInt(d)));}break;case'root':{if(args.length!==2||!Number.isInteger(x)||x===0)throw Error('domain');const b=args[1].value;n=b<0&&Math.abs(x%2)===1?-((-b)**(1/x)):b**(1/x);break;}default:throw Error('syntax');}return value(n);};
 const atom=()=>{if(++depth>100)throw Error('limit');let a,t=tokens[i++];if(t==='('){a=sum();if(tokens[i++]!==')')throw Error('syntax');}else if(/^\d*\.?\d+$/.test(t||''))a=number(t);else if(t==='pi')a=value(Math.PI);else if(t==='e')a=value(Math.E);else if(t==='Ans'||t==='ans')a=typeof ans==='number'?value(ans):ans;else if(tokens[i]==='('){i++;const args=[sum()];while(tokens[i]===','){i++;args.push(sum())}if(tokens[i++]!==')'||(t!=='root'&&args.length!==1))throw Error('syntax');a=call(t,args);}else throw Error('syntax');depth--;while(tokens[i]==='!'||tokens[i]==='%'){const op=tokens[i++];if(op==='%')a=operation('/',a,number('100'));else{if(!Number.isInteger(a.value)||a.value<0||a.value>170)throw Error('domain');let n=1n;for(let j=2n;j<=BigInt(a.value);j++)n*=j;a=value(Number(n),[n,1n]);}}return a;};
 const power=()=>{const a=atom();return tokens[i]==='^'?(i++,operation('^',a,unary())):a;};
 const unary=()=>tokens[i]==='-'?(i++,operation('-',number('0'),unary())):tokens[i]==='+'?(i++,unary()):power();
 const product=()=>{let a=unary();while(i<tokens.length){let op=tokens[i];if(op==='*'||op==='/'){i++;a=operation(op,a,unary());}else if(op==='('||/^[A-Za-z]/.test(op)){a=operation('*',a,unary());}else break;}return a;};
 const sum=()=>{let a=product();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++];a=operation(op,a,product())}return a;};
 const result=sum();if(i!==tokens.length)throw Error('syntax');return result;
}
export function formatResult(result,exact=false){if(exact&&result.exact){const[n,d]=result.exact;return d===1n?String(n):`${n}/${d}`;}return Number(result.value.toPrecision(12)).toString();}
